import React from "react";
import Footer from "./Footer";
import Navbar from "./Navbar";
import { jwtDecode } from "jwt-decode";

function Cart({ cartItems, onRemove, onCheckout }) {

  const token = localStorage.getItem("token");
  const currentUser = jwtDecode(token);

  const handleCheckout = async () => {
    if (!currentUser) {
      alert("You must be logged in to checkout");
      return;
    }

    if (!cartItems || cartItems.length === 0) {
      alert("Cart is empty");
      return;
    }

    try {
      const response = await fetch("http://localhost:5009/api/orders/checkout", {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          cartItems,
          buyerId: currentUser.id,
          buyerEmail: currentUser.email
        })
      });

      if (!response.ok) throw new Error("Checkout failed");

      // 🔥 IMPORTANT: send purchased items to parent
      if (onCheckout) onCheckout(cartItems);

      alert("Checkout successful!");
    } catch (err) {
      console.error(err);
      alert("Checkout failed");
    }
  };

  return (
    <>
      <Navbar/>
      <div className="Cart">
        {cartItems.length === 0 ? (
          <div className="HeadMo">
            <h1>No Orders!</h1>
          </div>
        ) : (
          <>
            <ul className="CartList">
              {cartItems.map((item) => (
                <li key={item._id}>
                  <div className="bashden">
                    <strong>{item.title}</strong>
                    <span>{item.para}</span>
                    <span>{item.price} USD</span>
                    <button onClick={() => onRemove(item._id)}>
                      Remove
                    </button>
                  </div>
                </li>
              ))}
            </ul>

            <div className="Btn-Kiddo">
              <button className="checkout-button" onClick={handleCheckout}>
                Checkout
              </button>
            </div>
          </>
        )}
      </div>
      <Footer/>
    </>
  );
}

export default Cart;
